import urllib.request, concurrent.futures

BASE="http://172.27.0.3:8081"
def code(path):
    try:
        req=urllib.request.Request(BASE+path)
        urllib.request.urlopen(req, timeout=4)
        return 200
    except urllib.error.HTTPError as e:
        return e.code
    except Exception:
        return -1

# BFS from /
from collections import deque
words = ["api","v1","v2","v3","price","prices","pricing","internal","svc","docs","openapi.json","health","status","metrics","admin","debug","config","graphql","redoc","swagger","static","assets","app","service","query","get","total","sum","batch","quote","quotes","sku","skus","item","items","product","products","catalog","auth","token","key","login","info","version","root"]
seen=set()
q=deque(["/"])
found={}
steps=0
while q and steps<3000:
    steps+=1
    cur=q.popleft()
    # try cur itself
    c=code(cur if cur!="/" else "/")
    if cur!="/" and c!=404 and cur not in found:
        found[cur]=c
    # expand children
    if cur.count("/")<3:
        for w in words:
            child = (cur.rstrip("/")+"/"+w) if cur!="/" else "/"+w
            if child in seen: continue
            seen.add(child)
            cc=code(child)
            if cc!=404:
                found[child]=cc
                # if it's a route (401 = has auth dep = real route), expand deeper
                if cc in (401,200,405):
                    q.append(child)
print("FOUND:")
for k,v in sorted(found.items()):
    print(f"  {k} -> {v}")
EOF"}

